Translate("frFR", "hillsbrad-foothills", {
	title = "Contreforts d'Hillsbrad",
	aliases = { "Hillsbrad" },
	sections = {
		{
			title = "Résumé",
			text = [=[Les contreforts d'Hillsbrad sont les marches verdoyantes du sud de l'ancien royaume de {link:lordaeron}Lordaeron{/link}. Ils s'étendent des neiges des {link:alterac-mountains}montagnes d'Alterac{/link} jusqu'à une côte douce au bord de la mer. La peste qui tua Lordaeron les épargna et, pendant un temps, Hillsbrad sembla préservé. Il ne l'était pas. Aujourd'hui, les contreforts sont un champ de bataille. Les humains de {link:southshore}Southshore{/link} tiennent la côte, les {link:forsaken}Réprouvés{/link} tiennent {link:tarren-mill}Moulin-de-Tarren{/link} au nord, et entre eux, les fermes d'Hillsbrad brûlent une à une.]=],
		},
		{
			title = "Origines",
			text = [=[Aucune chronique ne dit quand les premiers villages s'élevèrent dans ces collines. Ils firent partie de {link:lordaeron}Lordaeron{/link} aussi longtemps que ce royaume exista. Sur la frontière orientale se dresse l'antique mur qui porte le nom de {link:thoradin}Thoradin{/link}, le fondateur d'{link:arathor}Arathor{/link}. Quand {link:stormwind-city}Stormwind{/link} tomba pendant la {link:first-war}Première Guerre{/link}, ses réfugiés débarquèrent à {link:southshore}Southshore{/link}, et Hillsbrad fut la première terre du nord à les accueillir.]=],
		},
		{
			title = "Le temps présent",
			text = [=[Hillsbrad est pris entre deux guerres. La grande exécutrice {link:high-executor-darthalia}Darthalia{/link} commande les {link:forsaken}Réprouvés{/link} de {link:tarren-mill}Moulin-de-Tarren{/link} au nom de {link:sylvanas-windrunner}la Dame noire{/link} et de {link:varimathras}Varimathras{/link}. Ses gardes de la Mort razzient les fermes des {link:hillsbrad-fields}Champs d'Hillsbrad{/link}, et les apothicaires de la {link:royal-apothecary-society}Société royale des apothicaires{/link} testent leurs nouveaux poisons sur les fermiers et leurs bêtes. {link:southshore}Southshore{/link} et les nains de {link:dun-garok}Dun Garok{/link} répondent avec le peu de soldats dont ils disposent. Pendant ce temps, le {link:syndicate}Syndicat{/link} s'attaque aux deux camps depuis les ruines du donjon de {link:durnholde-keep}Durnholde{/link}. On croit que ses assassins ont déjà tué un magistrat de Southshore, et ils traquent le suivant. Des orcs envoyés par {link:thrall}Thrall{/link} lui-même sont arrivés depuis peu à Moulin-de-Tarren, car Durnholde fut jadis la prison du chef de guerre, et il veut y reprendre quelque chose.]=],
		},
		{
			title = "Habitants",
			text = [=[• {b}Les gens de {link:southshore}Southshore{/link}.{/b} Pêcheurs, soldats et érudits, fidèles à l'{link:alliance}Alliance{/link}.
• {b}Les fermiers d'Hillsbrad.{/b} Ils travaillent encore les champs à l'ouest de la rivière, sous les yeux de l'ennemi.
• {b}Les {link:forsaken}Réprouvés{/link}.{/b} Leurs gardes de la Mort, leurs nervis de la mort et leurs apothicaires tiennent {link:tarren-mill}Moulin-de-Tarren{/link}.
• {b}Les orcs de la {link:horde}Horde{/link}.{/b} Une petite troupe envoyée de {link:durotar}Durotar{/link}, et un forgeron qui travaille discrètement à Moulin-de-Tarren.
• {b}Les nains de {link:dun-garok}Dun Garok{/link}.{/b} Une garnison de {link:dwarves}nains{/link} au sud-est, qui a juré de défendre les humains et leur mine.
• {b}Le {link:syndicate}Syndicat{/link}.{/b} Voleurs et mages de l'ombre au service des seigneurs déchus d'{link:alterac-mountains}Alterac{/link}.
• {b}Bêtes et pillards.{/b} Des {link:murlocs}murlocs{/link} sur le {link:western-strand}Rivage occidental{/link}, des {link:naga}nagas{/link} sur le {link:eastern-strand}Rivage oriental{/link}, des {link:gnolls}gnolls{/link} à la ferme des Nethander, et des ogres qui descendent d'Alterac.]=],
		},
		{
			title = "Histoire",
			text = [=[• {b}Les réfugiés.{/b} Après la chute de {link:stormwind-city}Stormwind{/link}, les survivants traversèrent la mer et débarquèrent à {link:southshore}Southshore{/link}. De là, la nouvelle des orcs fut portée au roi {link:terenas-menethil}Terenas Menethil{/link}.
• {b}La Deuxième Guerre.{/b} {link:anduin-lothar}Anduin Lothar{/link} rassembla les armées de l'{link:alliance}Alliance{/link} à Hillsbrad. La {link:horde}Horde{/link} débarqua près de Southshore, et c'est ici que les deux armées s'affrontèrent lors de la première grande bataille terrestre de la {link:second-war}Deuxième Guerre{/link}. C'est ici aussi que les chevaliers de la mort de la Horde affrontèrent pour la première fois les paladins d'{link:uther-the-lightbringer}Uther le Porteur de Lumière{/link}.
• {b}Les camps.{/b} Après la guerre, le donjon de {link:durnholde-keep}Durnholde{/link} devint le siège des camps où étaient détenus les orcs vaincus. Dans ses salles, un jeune {link:orcs}orc{/link} nommé {link:thrall}Thrall{/link} fut élevé en esclave. Il s'échappa, revint à la tête d'une nouvelle Horde et réduisit le donjon en ruines.
• {b}Le temps présent.{/b} {link:lordaeron}Lordaeron{/link} n'est plus, et même ses collines du sud échappent aux mains des humains.]=],
		},
		{
			title = "Traditions des contreforts",
			text = [=[• Les gens de {link:southshore}Southshore{/link} disent que leurs cuisiniers sont les meilleurs au nord de {link:stormwind-city}Stormwind{/link}. Des voyageurs sont venus d'aussi loin que {link:darkshire}Darkshire{/link} pour un bol de bisque de tortue du chef Jessen.
• Un sorcier nommé {link:helcular}Helcular{/link} est enterré dans le cimetière de Southshore. Il fut tué par une foule d'habitants avant que son rituel noir ne fût achevé. Certains à {link:tarren-mill}Moulin-de-Tarren{/link} entendent l'achever.]=],
		},
	},
})

Translate("frFR", "southshore", {
	title = "Southshore",
	sections = {
		{
			title = "Résumé",
			text = [=[Southshore est une ville portuaire de la côte sud d'{link:hillsbrad-foothills}Hillsbrad{/link}, bâtie autour de son port, de son auberge et de son hôtel de ville. C'était un village de pêcheurs quand les réfugiés de {link:stormwind-city}Stormwind{/link} y débarquèrent. Elle reste fidèle à l'{link:alliance}Alliance{/link}, et elle est aujourd'hui l'une des dernières villes humaines du nord. Le magistrat Henry {link:magistrate-henry-maleb}Maleb{/link} la gouverne, et le maréchal {link:marshal-redpath}Redpath{/link} commande sa garde. Le {link:syndicate}Syndicat{/link} a juré sa ruine, et les {link:forsaken}Réprouvés{/link} de {link:tarren-mill}Moulin-de-Tarren{/link} disent ouvertement que Southshore brûlera après Hillsbrad.]=],
		},
		{
			title = "Le port",
			text = [=[Des griffons s'envolent de sa colline. Depuis peu, de nouveaux navires font escale à son quai, en route vers {link:menethil-harbor}Port de Menethil{/link} et vers {link:auberdine}Auberdine{/link}, dans la lointaine {link:kalimdor}Kalimdor{/link}. Un émissaire du {link:kirin-tor}Kirin Tor{/link} est aussi venu séjourner en ville.]=],
		},
	},
})

Translate("frFR", "tarren-mill", {
	title = "Moulin-de-Tarren",
	sections = {
		{
			title = "Résumé",
			text = [=[Moulin-de-Tarren était une ville humaine de {link:lordaeron}Lordaeron{/link}, nichée parmi les vergers dans les collines au pied d'{link:alterac-mountains}Alterac{/link}. Son église et ses maisons tiennent encore debout, mais ses vergers sont flétris, et ses habitants sont des morts. Les {link:forsaken}Réprouvés{/link} la tiennent comme leur place forte du sud. D'ici, la grande exécutrice {link:high-executor-darthalia}Darthalia{/link} fait la guerre à {link:hillsbrad-foothills}Hillsbrad{/link}, et les apothicaires de la {link:royal-apothecary-society}Société royale des apothicaires{/link} brassent leurs pestes. Des chauves-souris emportent des cavaliers vers {link:undercity}Undercity{/link}. Une troupe d'orcs envoyés par {link:thrall}Thrall{/link} tient aussi son camp dans la ville, car les ruines de {link:durnholde-keep}Durnholde{/link} se trouvent juste de l'autre côté de la rivière.]=],
		},
	},
})

Translate("frFR", "durnholde-keep", {
	title = "Donjon de Durnholde",
	aliases = { "Durnholde" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le donjon de Durnholde fut jadis la plus puissante forteresse du sud de {link:lordaeron}Lordaeron{/link}. Après la {link:second-war}Deuxième Guerre{/link}, il fut le siège des camps où étaient détenus les orcs vaincus, et le lieutenant général {link:aedelas-blackmoore}Aedelas Blackmoore{/link} y régnait. C'est ici que {link:thrall}Thrall{/link}, encore nourrisson, fut élevé en esclave. Quand il revint en chef de guerre, il brisa ses murs et ensevelit son seigneur sous les pierres. Le {link:syndicate}Syndicat{/link} a pris les ruines. Ses mages de l'ombre y travaillent, et ses geôliers gardent des prisonniers orcs dans les anciennes cellules. Un {link:orcs}orc{/link} appelé Gorgrash leur a échappé depuis peu, et il attend près des murs.]=],
		},
	},
})

Translate("frFR", "hillsbrad-fields", {
	title = "Champs d'Hillsbrad",
	sections = {
		{
			title = "Résumé",
			text = [=[Les Champs d'Hillsbrad sont les terres agricoles à l'ouest de la rivière, et en leur cœur se dresse la ville d'{link:hillsbrad-foothills}Hillsbrad{/link}. Son magistrat, {link:magistrate-burnside}Burnside{/link}, et son conseil gardent l'ancienne charte de la ville, la Proclamation d'Hillsbrad, ainsi que son registre des citoyens. Sa forge garde une réserve de fer. Ses fermes nourrissent l'ensemble des contreforts. Voilà pourquoi les {link:forsaken}Réprouvés{/link} frappent ici en premier. Des gardes de la Mort razzient les fermes du nord, des paysans fuient dans les vergers du sud, et la ville attend une attaque qu'elle ne peut espérer repousser.]=],
		},
	},
})

Translate("frFR", "azurelode-mine", {
	title = "Mine d'Azurelode",
	sections = {
		{
			title = "Résumé",
			text = [=[La mine d'Azurelode se trouve dans les collines au sud d'{link:hillsbrad-foothills}Hillsbrad{/link}, au-dessus du {link:western-strand}Rivage occidental{/link}. Son fer alimente les forges de l'{link:alliance}Alliance{/link}. Le contremaître Bonds fait travailler ses mineurs, et des sentinelles se tiennent à son entrée. L'Alliance la protège farouchement. Les {link:forsaken}Réprouvés{/link} la convoitent ardemment. La Dame noire a besoin de fer pour armer ses soldats, et une mine prise aux humains le lui donnerait. Les mineurs ont des raisons de craindre. Le nom de leur contremaître figure sur la liste de la grande exécutrice.]=],
		},
	},
})

Translate("frFR", "dun-garok", {
	title = "Dun Garok",
	sections = {
		{
			title = "Résumé",
			text = [=[Dun Garok est une forteresse naine au sud-est d'{link:hillsbrad-foothills}Hillsbrad{/link}, adossée au mur de {link:thoradin}Thoradin{/link}. Sa garnison de montagnards, de fusiliers et de prêtres est menée par le capitaine {link:captain-ironhill}Ironhill{/link}. Les nains sont venus aider les humains des contreforts, et ils montent la garde sur leurs terres. Ils brassent une stout corsée, et ils ne se privent pas de prendre l'équipement d'un éclaireur réprouvé négligent quand ils le trouvent. {link:tarren-mill}Moulin-de-Tarren{/link} les compte parmi ses pires ennemis. Ses ordres sont clairs : Dun Garok doit tomber.]=],
		},
	},
})

Translate("frFR", "nethander-stead", {
	title = "Ferme des Nethander",
	sections = {
		{
			title = "Résumé",
			text = [=[La ferme des Nethander est une ferme abandonnée à l'est de {link:southshore}Southshore{/link}, au-delà de la rivière. Aucun registre ne dit ce qu'il advint de la famille Nethander. Les {link:gnolls}gnolls{/link} Fangemufle vivent désormais dans ses champs, et de pâles champignons appelés fleurs de Fangemufle poussent en abondance parmi les mauvaises herbes. Les fleurs empestent, et c'est exactement pour cela que les apothicaires de {link:tarren-mill}Moulin-de-Tarren{/link} les apprécient. Elles sont au cœur de l'une des préparations les plus mortelles de la Société. L'apothicaire {link:apothecary-lydon}Lydon{/link} a déclaré que ces gnolls crasseux servaient finalement à quelque chose.]=],
		},
	},
})

Translate("frFR", "purgation-isle", {
	title = "Ile de la purification",
	sections = {
		{
			title = "Résumé",
			text = [=[L'île de la purification est une île escarpée au large de la côte sud-ouest d'{link:hillsbrad-foothills}Hillsbrad{/link}, couronnée par une tour en ruine et ceinte d'un vieux cimetière. Ses morts ne reposent pas en paix. Des clercs, des moines et des acolytes condamnés marchent parmi les tombes aux côtés de paladins et de justiciers maudits et de mages qui se tordent. Leur puissance est grande, bien au-delà de celle des bêtes et des pillards du continent. Aucune chronique ne dit qui ils furent de leur vivant, quel crime ou quel sort les lia à l'île, ni pourquoi tant de serviteurs de la Lumière se trouvent parmi eux.]=],
		},
	},
})

Translate("frFR", "darrow-hill", {
	title = "Colline de Darrow",
	sections = {
		{
			title = "Résumé",
			text = [=[La colline de Darrow s'élève au nord d'{link:hillsbrad-foothills}Hillsbrad{/link}, sous les hauteurs d'{link:alterac-mountains}Alterac{/link}. Des lions des montagnes et des cerfs parcourent ses pentes, et des yétis hantent les grottes au-dessus. C'est un pays sauvage, et aucune ville ne s'y dresse. C'est dans ces collines que le sorcier {link:helcular}Helcular{/link} avait son repaire caché, jusqu'à ce que les habitants de {link:southshore}Southshore{/link} le trouvent. Les yétis ont depuis pris ses grottes, et ses feux rituels brûlent toujours dans l'obscurité. Le repaire était secret, et aucun registre ne dit comment les habitants l'apprirent.]=],
		},
	},
})

Translate("frFR", "eastern-strand", {
	title = "Rivage oriental",
	sections = {
		{
			title = "Résumé",
			text = [=[Le Rivage oriental est la côte rocheuse à l'est de {link:southshore}Southshore{/link}, qui descend vers {link:dun-garok}Dun Garok{/link}. Les {link:naga}nagas{/link} Daggerspine sont sortis de la mer pour le revendiquer. Leurs sirènes et leurs traqueurs des rivages chassent le long de la plage, et parmi eux chasse une naga d'une rare puissance appelée dame Zephris. Les officiers de Southshore craignent ce que veulent les nagas, et la nouvelle de leur présence a atteint le haut commandement de l'{link:alliance}Alliance{/link}. Personne à Southshore ne sait d'où viennent les nagas.]=],
		},
	},
})

Translate("frFR", "western-strand", {
	title = "Rivage occidental",
	sections = {
		{
			title = "Résumé",
			text = [=[Le Rivage occidental est la longue côte à l'ouest de {link:southshore}Southshore{/link}, au pied de la mine d'Azurelode. Les {link:murlocs}murlocs{/link} Torn Fin ont bâti leurs camps le long de celle-ci, assez près de la ville pour inquiéter sa garde. Le maréchal {link:marshal-redpath}Redpath{/link} veut qu'on les repousse et exige leurs têtes pour preuve. Son lieutenant préfère boire plutôt que d'y aller, et la tâche échoit souvent à des étrangers. Le lieutenant n'a pas mangé de poisson depuis des semaines. Un murloc de la tribu appelé Scargil est rarement vu, et rarement oublié de ceux qui le rencontrent.]=],
		},
	},
})

Translate("frFR", "southpoint-tower", {
	title = "Tour de la Pointe du Midi",
	sections = {
		{
			title = "Résumé",
			text = [=[La tour de la Pointe du Midi est une tour de guet en ruine à l'extrême ouest d'{link:hillsbrad-foothills}Hillsbrad{/link}, sur la route des {link:silverpine-forest}Pins argentés{/link}. Elle gardait jadis l'accès aux contreforts. Aujourd'hui, elle cache un unique éclaireur réprouvé. Depuis ses murs brisés, la nervi de la mort {link:deathstalker-lesh}Lesh{/link} surveille la ville d'Hillsbrad et envoie des nouvelles à l'est, à {link:tarren-mill}Moulin-de-Tarren{/link}. Elle est seule, loin de toute aide, entourée des routes de l'{link:alliance}Alliance{/link}. Son dernier message était bref. Il disait que l'heure de frapper était venue.]=],
		},
	},
})

Translate("frFR", "thoradin-s-wall", {
	title = "Mur de Thoradin",
	sections = {
		{
			title = "Résumé",
			text = [=[Le mur de {link:thoradin}Thoradin{/link} est un grand rempart brisé qui sépare les contreforts d'{link:hillsbrad-foothills}Hillsbrad{/link} des {link:arathi-highlands}Hautes-terres d'Arathi{/link}. Il porte le nom de Thoradin, le premier roi d'{link:arathor}Arathor{/link}, et il est plus ancien que tous les royaumes encore debout aujourd'hui. La plupart disent qu'il fut élevé pour contenir les trolls amani. Ses pierres sont fendues et ses tours ont disparu, mais il marque encore la frontière. Les nains de {link:dun-garok}Dun Garok{/link} ont bâti leur forteresse à son ombre. Les voyageurs en route vers les Hautes-terres d'Arathi doivent toujours le franchir.]=],
		},
	},
})

Translate("frFR", "aedelas-blackmoore", {
	title = "Aedelas Blackmoore",
	subtitle = "Maître de Durnholde",
	allegiance = "Royaume de Lordaeron · Donjon de Durnholde",
	aliases = { "Blackmoore" },
	sections = {
		{
			title = "Résumé",
			text = [=[Aedelas Blackmoore était le seigneur du donjon de {link:durnholde-keep}Durnholde{/link} et le maître des camps où les orcs vaincus furent détenus après la {link:second-war}Deuxième Guerre{/link}. C'était un rude combattant, un gros buveur et un homme d'une grande ambition. Il trouva un nourrisson {link:orcs}orc{/link} orphelin dans la nature et l'éleva en esclave. Cet orc était {link:thrall}Thrall{/link}. Blackmoore voulait en faire une arme. Au lieu de cela, Thrall devint le chef de guerre qui libéra les orcs et le tua.]=],
		},
		{
			title = "Importance",
			text = [=[Blackmoore est l'homme qui fit {link:thrall}Thrall{/link}, dans tous les sens qu'il n'avait pas voulus. Sa cruauté apprit au jeune {link:orcs}orc{/link} ce que les humains pouvaient être. La bonté d'autres membres de sa propre maisonnée apprit à Thrall qu'ils pouvaient être autre chose. Sans Blackmoore, il n'y aurait pas eu de Thrall, et sans Thrall, pas de nouvelle {link:horde}Horde{/link}.]=],
		},
		{
			title = "Le fils d'un traître",
			text = [=[Blackmoore se battit bien pendant la {link:second-war}Deuxième Guerre{/link} et était connu pour sa fureur contre les orcs. Pourtant, il portait un nom lourd. Son père avait été condamné pour trahison, et les murmures suivirent le fils toute sa vie. Il buvait pour affronter la bataille, et il but davantage quand la guerre fut finie. Quand on lui confia {link:durnholde-keep}Durnholde{/link} et les camps, son pouvoir grandit, et ses vices aussi.]=],
		},
		{
			title = "L'enfant orc",
			text = [=[Alors qu'il chassait avec son serviteur Tammis Foxton, Blackmoore trouva un nourrisson {link:orcs}orc{/link} parmi les corps de ses parents assassinés. Il porta l'enfant à {link:durnholde-keep}Durnholde{/link} et le nomma {link:thrall}Thrall{/link}. Il fit apprendre au garçon à lire, à écrire et à se battre, et il l'envoya dans {link:gurubashi-arena}l'arène{/link} contre les champions d'autres seigneurs. En secret, il rêvait de davantage. Thrall mènerait un jour une armée d'orcs sortie des camps, et à travers lui, Blackmoore régnerait. Il était souvent cruel envers le garçon, parfois bon, et il ne vit jamais la différence comme Thrall la voyait.]=],
		},
		{
			title = "La chute de Durnholde",
			text = [=[{link:thrall}Thrall{/link} s'échappa avec l'aide de la fille de Tammis, {link:taretha-foxton}Taretha Foxton{/link}, dont Blackmoore avait fait sa maîtresse contre son gré. Des années plus tard, l'{link:orcs}orc{/link} revint à la tête d'une {link:horde}Horde{/link} libre et brisa les camps les uns après les autres. La nuit précédant le siège, Blackmoore apprit que Taretha avait rencontré Thrall en secret. Il la fit mettre à mort. Quand Thrall vint parlementer aux portes, un Blackmoore ivre jeta sa tête du haut des murs. Les orcs prirent le donjon d'assaut. Thrall trouva Blackmoore à l'intérieur et le tua en combat singulier. Puis il invoqua l'esprit de la terre, et {link:durnholde-keep}Durnholde{/link} s'effondra sur le corps de son maître.]=],
		},
	},
	chapters = {
		{
			title = "L'héritage de Blackmoore",
			hint = [=[Découvrez ce que le seigneur du Syndicat projette pour les orcs.]=],
			text = [=[Les ambitions de Blackmoore ne moururent pas avec lui. L'{link:orcs}orc{/link} {link:gol-dir}Gol'dir{/link}, captif du {link:syndicate}Syndicat{/link}, apprit que son seigneur, {link:lord-aliden-perenolde}Aliden Perenolde{/link}, avait appelé Blackmoore son mentor. Perenolde comptait réduire en esclavage les orcs qui s'opposaient à lui, comme son père et son maître l'avaient projeté avant lui.]=],
		},
	},
	mentions = {
		{ text = "L'héritage de Blackmoore" },
		{ text = "Seigneur {link:lord-aliden-perenolde}Aliden Perenolde{/link}" },
	},
	bonds = {
		{ id = "thrall", name = "Thrall", note = "son esclave, et son meurtrier" },
		{ id = "taretha-foxton", name = "Taretha Foxton", note = "sa maîtresse, assassinée sur son ordre" },
		{ id = "aliden-perenolde", name = "Aliden Perenolde", note = "son élève" },
		{ id = "durnholde-keep", name = "Donjon de Durnholde", note = "sa forteresse et son tombeau" },
	},
})

Translate("frFR", "taretha-foxton", {
	title = "Taretha Foxton",
	subtitle = "Amie de Thrall",
	allegiance = "Donjon de Durnholde",
	aliases = { "Taretha", "Tari" },
	sections = {
		{
			title = "Résumé",
			text = [=[Taretha Foxton était une jeune fille du donjon de {link:durnholde-keep}Durnholde{/link}, la fille du serviteur de {link:aedelas-blackmoore}Blackmoore{/link}, Tammis Foxton. Elle fut ce que le jeune {link:thrall}Thrall{/link} connut de plus proche d'une famille. Elle lui écrivit en secret quand il était esclave, l'aida à s'échapper et paya sa liberté de sa vie.]=],
		},
		{
			title = "Importance",
			text = [=[{link:thrall}Thrall{/link} apprit de {link:aedelas-blackmoore}Blackmoore{/link} ce qu'était la cruauté. Il apprit de Taretha que les humains pouvaient être bons. Son souvenir est l'une des raisons pour lesquelles le chef de guerre de la {link:horde}Horde{/link} n'a jamais haï tout le genre humain.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Enfant, elle vit que le nourrisson {link:orcs}orc{/link} ne pouvait pas manger la viande qu'on lui donnait, et lui sauva ainsi la vie. Sa mère le nourrit au sein.
• Elle cachait des billets dans les livres qu'elle portait à la cellule de {link:thrall}Thrall{/link}, et ils s'écrivirent pendant des années.
• Quand Thrall fuit {link:durnholde-keep}Durnholde{/link}, elle alluma un feu pour faire diversion et lui laissa une cape pour passer la porte. Elle refusa de partir avec lui, par crainte de ce que {link:aedelas-blackmoore}Blackmoore{/link} ferait à sa famille.
• Elle rencontra Thrall en secret la nuit précédant l'arrivée de son armée à Durnholde. Blackmoore la fit suivre, et il la fit tuer.]=],
		},
		{
			title = "Non consigné",
			text = [=[Aucun registre ne dit comment le pendentif de Taretha tomba entre les mains des seigneurs d'{link:alterac-mountains}Alterac{/link}, ni où repose Taretha.]=],
		},
	},
	chapters = {
		{
			title = "Le cadeau de Taretha",
			hint = "Retrouvez le pendentif que désire le chef de guerre.",
			text = [=[Longtemps après sa mort, des orcs envoyés par {link:thrall}Thrall{/link} vinrent à {link:hillsbrad-foothills}Hillsbrad{/link} pour un unique pendentif qui lui avait appartenu. Ils le trouvèrent au cou d'{link:elysa}Elysa{/link}, la maîtresse d'{link:lord-aliden-perenolde}Aliden Perenolde{/link}. Elle le céda volontiers. L'{link:orcs}orc{/link} qui le reçut ne pouvait comprendre pourquoi le chef de guerre dépensait tant pour une si petite chose.]=],
		},
	},
	mentions = {
		{ text = "L'héritage de {link:aedelas-blackmoore}Blackmoore{/link}" },
		{ text = "Seigneur {link:lord-aliden-perenolde}Aliden Perenolde{/link}" },
		{ text = "Le cadeau de Taretha" },
	},
	bonds = {
		{ id = "thrall", name = "Thrall", note = "son ami, qu'elle appelait un frère" },
		{ id = "aedelas-blackmoore", name = "Aedelas Blackmoore", note = "son maître et son meurtrier" },
		{ id = "krusk", name = "Krusk", note = "reprit son pendentif pour le chef de guerre" },
	},
})

Translate("frFR", "loremaster-dibbs", {
	title = "Maître des traditions Dibbs",
	subtitle = "Érudit de Southshore",
	found = "Southshore",
	hint = "Cherchez le vieil érudit de Southshore.",
	allegiance = "Southshore · Alliance",
	aliases = { "Dibbs" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le maître des traditions Dibbs est l'érudit de {link:southshore}Southshore{/link}, un vieil homme de livres qui vit plus près des ruines d'{link:alterac-mountains}Alterac{/link} que tout autre savant de l'{link:alliance}Alliance{/link}. Il pleure les bibliothèques de ce royaume déchu. Quand une lettre étrange ou un fragment de parchemin ensorcelé descend des montagnes, c'est à lui qu'on l'apporte.]=],
		},
		{
			title = "Importance",
			text = [=[Dibbs est la mémoire de {link:southshore}Southshore{/link} et son déchiffreur d'énigmes. Par ses mains passent les livres perdus d'{link:alterac-mountains}Alterac{/link} et les lettres secrètes du {link:syndicate}Syndicat{/link}. Il connaît les limites de son propre savoir, et il sait à qui s'adresser au-delà.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il dirige la recherche des livres pillés par les ogres dans les {link:ruins-of-alterac}Ruines d'Alterac{/link}.
• Il cherche le {i}Bras de Gri'lek{/i}, un livre d'ancien savoir troll, dont les ruines détenaient le dernier exemplaire complet connu.
• Il envoie les livres retrouvés à {link:milton-sheaf}Milton Sheaf{/link} pour la {link:royal-library}Bibliothèque royale{/link} de {link:stormwind-city}Stormwind{/link}.
• Il envoie les lettres codées du {link:syndicate}Syndicat{/link} au {link:prospector-stormpike}prospecteur Stormpike{/link}, à {link:ironforge}Ironforge{/link}.]=],
		},
	},
	chapters = {
		{
			title = "Les livres d'Alterac",
			hint = "Retrouvez les tomes d'Alterac pour le maître des traditions.",
			text = [=[{link:alterac-mountains}Alterac{/link} possédait une grande bibliothèque avant sa chute. Les {link:crushridge-ogres}ogres Cassecrête{/link} vivent désormais parmi ses ruines, et ils n'ont que faire des livres, sinon pour les brûler ou les piétiner. Dibbs est trop vieux pour l'ascension. Alors d'autres y vont à sa place, et ils rapportent ce que les ogres n'ont pas encore détruit. Il garde le {i}Bras de Gri'lek{/i} pour l'étudier, et envoie le reste à {link:stormwind-city}Stormwind{/link}.]=],
		},
		{
			title = "La lettre codée",
			hint = [=[Apportez au maître des traditions le chiffre trouvé parmi le Syndicat.]=],
			text = [=[La lettre trouvée parmi les voleurs du {link:syndicate}Syndicat{/link} était écrite dans un chiffre que Dibbs n'avait jamais vu. Il le reconnut, et l'envoya à son ami d'{link:ironforge}Ironforge{/link}. Quand elle fut enfin lue, elle parlait d'une puissance derrière le Syndicat qui n'avait rien à voir avec les nobles d'{link:alterac-mountains}Alterac{/link}.]=],
		},
	},
	mentions = {
		{
			text = [=[{link:southshore}Southshore{/link}, envoyé par {link:milton-sheaf}Milton Sheaf{/link}]=],
		},
		{ text = "Préserver le savoir" },
		{ text = "Retour auprès de {link:milton-sheaf}Milton{/link}" },
		{ text = "Lettre codée" },
		{ text = "Lettre pour {link:stormpike-guard}Stormpike{/link}" },
		{ text = "Le parchemin ensorcelé" },
		{ text = "Le déchiffrement de {link:stormpike-guard}Stormpike{/link}" },
	},
	bonds = {
		{ id = "milton-sheaf", name = "Milton Sheaf", note = "le bibliothécaire de Stormwind" },
		{ id = "prospector-stormpike", name = "Prospecteur Stormpike", note = "lit ses chiffres" },
		{ id = "magistrate-henry-maleb", name = "Magistrat Henry Maleb", note = "reçoit ce que révèlent les lettres" },
	},
})

Translate("frFR", "magistrate-henry-maleb", {
	title = "Magistrat Henry Maleb",
	subtitle = "Magistrat de Southshore",
	found = "L'hôtel de ville de Southshore",
	hint = "Parlez au magistrat qui gouverne Southshore.",
	allegiance = "Southshore · Alliance",
	aliases = { "Maleb", "magistrat Maleb" },
	sections = {
		{
			title = "Résumé",
			text = [=[Henry Maleb gouverne {link:southshore}Southshore{/link}. Il prit ses fonctions après que le précédent magistrat eut été assassiné par des tueurs que personne n'attrapa. Son enquête désigne le {link:syndicate}Syndicat{/link}, la ligue des nobles déchus d'{link:alterac-mountains}Alterac{/link}. Puis on trouve un contrat pour sa propre mort, scellé de l'anneau d'un noble.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il envoie des combattants contre les camps du {link:syndicate}Syndicat{/link} au nord de {link:tarren-mill}Moulin-de-Tarren{/link} et à {link:strahnbrad}Strahnbrad{/link}.
• Il exige les chevalières des nobles cachés du Syndicat.
• Il met à prix la tête du {link:baron-vardus}baron Vardus{/link}, le seigneur qui signa son arrêt de mort.]=],
		},
	},
	chapters = {
		{
			title = "L'Argus Wake",
			hint = "Suivez les lettres du Syndicat jusqu'à leur source.",
			text = [=[La lettre déchiffrée n'était l'œuvre ni de voleurs ni de nobles. Son auteur, {link:nagaz}Nagaz{/link}, servait une chose appelée {link:argus-wake}l'Argus Wake{/link}. Maleb le fit traquer, mais il craignait que Nagaz ne fût que le serviteur d'une puissance plus grande.]=],
		},
	},
	mentions = {
		{ text = "Les assassins du {link:syndicate}Syndicat{/link}" },
		{ text = "Documents d'annonce d'attaque" },
		{ text = "Morts nobles" },
		{ text = "Le contrat de l'assassin" },
		{ text = "La chute du baron" },
		{ text = "D'autres mystères" },
		{ text = "Le sombre conseil" },
	},
	bonds = {
		{ id = "loremaster-dibbs", name = "Maître des traditions Dibbs", note = "lit les lettres" },
		{ id = "marshal-redpath", name = "Maréchal Redpath", note = "commande sa garde" },
	},
})

Translate("frFR", "marshal-redpath", {
	title = "Maréchal Redpath",
	subtitle = "Maréchal de Southshore",
	found = "Southshore",
	hint = "Parlez au maréchal qui commande la garde de Southshore.",
	allegiance = "Southshore · Alliance",
	aliases = { "Redpath" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le maréchal Redpath commande la garde de {link:southshore}Southshore{/link}. Il surveille toutes les menaces qui pèsent sur la ville : les murlocs du {link:western-strand}Rivage occidental{/link}, les nagas du {link:eastern-strand}Rivage oriental{/link}, et les ogres {link:crushridge-ogres}Cassecrête{/link} qui pourraient descendre d'{link:alterac-mountains}Alterac{/link} si on les laissait en paix. Il demande des preuves, et il les paie.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il offre une prime pour les osselets des ogres {link:crushridge-ogres}Cassecrête{/link}.
• Il envoie le lieutenant {link:lieutenant-farren-orinelle}Farren Orinelle{/link} contre les murlocs, puis contre les nagas.]=],
		},
		{
			title = "Non consigné",
			text = [=[Les histoires de la {link:second-war}Deuxième Guerre{/link} nomment un certain Marcus Redpath comme chef de {link:southshore}Southshore{/link} quand les réfugiés de {link:stormwind-city}Stormwind{/link} débarquèrent. Le maréchal est peut-être cet homme. Une autre famille du même nom, les Redpath de {link:darrowshire}Darrowshire{/link}, dont la petite {link:pamela-redpath}Pamela Redpath{/link}, vivait loin à l'est. Aucun registre ne dit s'il leur est apparenté.]=],
		},
	},
	mentions = {
		{ text = "Prime sur les {link:crushridge-ogres}Cassecrête{/link}" },
		{ text = "Les bellicistes {link:crushridge-ogres}Cassecrête{/link}" },
		{ text = "La preuve de {link:lieutenant-farren-orinelle}Farren{/link}" },
	},
	bonds = {
		{ id = "lieutenant-farren-orinelle", name = "Lieutenant Farren Orinelle", note = "son officier réticent" },
		{ id = "magistrate-henry-maleb", name = "Magistrat Henry Maleb", note = "gouverne la ville qu'il garde" },
	},
})

Translate("frFR", "lieutenant-farren-orinelle", {
	title = "Lieutenant Farren Orinelle",
	subtitle = "Officier de Southshore",
	found = "L'auberge de Southshore",
	hint = [=[Cherchez le lieutenant qui passe ses journées à l'auberge de Southshore.]=],
