	},
	bonds = {
		{ id = "marshal-redpath", name = "Maréchal Redpath", note = "son commandant" },
		{ id = "major-samuelson", name = "Major Samuelson", note = "son mentor à Stormwind" },
	},
})

Translate("frFR", "raleigh-the-devout", {
	title = "Raleigh le Dévot",
	subtitle = "Un croisé qui s'est détourné",
	found = "L'étage de l'auberge de Southshore",
	hint = [=[Cherchez l'ancien croisé qui reste à l'étage de l'auberge de Southshore.]=],
	allegiance = "Lumière sacrée",
	aliases = { "Raleigh" },
	sections = {
		{
			title = "Résumé",
			text = [=[Raleigh le Dévot servit jadis la {link:scarlet-crusade}Croisade écarlate{/link} avec fierté. Il croyait en sa cause : débarrasser le monde des morts-vivants. Au monastère de la Croisade, il vit des innocents torturés, accusés de porter la peste sans autre raison que de ne pas porter son tabard. Il partit, et il vit désormais tranquillement à {link:southshore}Southshore{/link}.]=],
		},
		{
			title = "Importance",
			text = [=[Certains membres de la Croisade croient encore que Raleigh est des leurs. Ceux qu'ils envoient auprès de lui apprennent plutôt la vérité sur l'ordre.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il appelle à la mort des chefs du {link:scarlet-monastery}Monastère écarlate{/link}, au nom de la {link:holy-light}Lumière sacrée{/link}, afin que la vraie cause puisse un jour être ranimée.]=],
		},
	},
	mentions = {
		{ text = "Sur la voie écarlate" },
		{ text = "Au nom de la Lumière" },
	},
	bonds = {
		{ id = "scarlet-crusade", name = "Croisade écarlate", note = "l'ordre qu'il a abandonné" },
	},
})

Translate("frFR", "innkeeper-anderson", {
	title = "Aubergiste Anderson",
	subtitle = "Aubergiste de Southshore",
	found = "L'auberge de Southshore",
	hint = "Parlez à l'aubergiste de Southshore.",
	allegiance = "Southshore",
	aliases = { "Anderson" },
	sections = {
		{
			title = "Résumé",
			text = [=[Anderson tient l'auberge de {link:southshore}Southshore{/link}, la maison la plus animée de la ville. Sous son toit se rassemblent des soldats au repos, des habitants, un ancien croisé et un {link:dwarves}nain{/link} rarement sobre. Les voyageurs fatigués venus de la colline aux griffons et du port trouvent chez lui un lit et un repas.]=],
		},
		{
			title = "Importance",
			text = [=[L'auberge est l'endroit où {link:southshore}Southshore{/link} parle. Sous un même toit, un lieutenant se plaint de son affectation, un ancien croisé reste dans sa chambre à l'étage, et un maître brasseur {link:dwarves}nain{/link} attend à la cave l'alcool de contrebande d'un débiteur.]=],
		},
		{
			title = "Non consigné",
			text = [=[On a peu écrit sur Anderson lui-même. Aucun registre ne donne son prénom ni ne dit depuis combien de temps il tient l'auberge.]=],
		},
	},
	bonds = {
		{ id = "brewmeister-bilger", name = "Maître brasseur Bilger", note = "boit dans sa cave" },
		{ id = "lieutenant-farren-orinelle", name = "Lieutenant Farren Orinelle", note = "boit à ses tables" },
	},
})

Translate("frFR", "brewmeister-bilger", {
	title = "Maître brasseur Bilger",
	subtitle = "Maître brasseur de Southshore",
	found = "La cave de l'auberge de Southshore",
	hint = [=[Cherchez le maître brasseur nain dans la cave de l'auberge de Southshore.]=],
	allegiance = "Southshore",
	aliases = { "Bilger" },
	sections = {
		{
			title = "Résumé",
			text = [=[Bilger est un {link:dwarves}nain{/link} qui ne quitte guère la cave de l'auberge de {link:southshore}Southshore{/link}. Il brasse et il boit, et il a le hoquet entre les deux. Un nain des {link:wetlands}Paluns{/link} lui doit une dette, et Bilger compte bien qu'elle soit payée en alcool de contrebande.]=],
		},
		{
			title = "Importance",
			text = [=[Le commerce de Bilger s'étend bien au-delà de {link:southshore}Southshore{/link}. Ses débiteurs vivent jusque dans les {link:wetlands}Paluns{/link}, de l'autre côté de la mer au sud.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• {link:foggy-mackreel}Foggy MacKreel{/link}, un {link:dwarves}nain{/link} des {link:wetlands}Paluns{/link} souvent en retard pour régler ses factures, lui doit une cuvée d'alcool de contrebande.
• Il soutient que rien ne réchauffe un nain par un jour frais comme l'alcool de contrebande de MacKreel.]=],
		},
		{
			title = "Non consigné",
			text = [=[Aucun registre ne dit comment Bilger vint à {link:southshore}Southshore{/link}.]=],
		},
	},
	mentions = {
		{
			text = [=[L'alcool de contrebande de {link:foggy-mackreel}MacKreel{/link}]=],
		},
	},
	bonds = {
		{ id = "innkeeper-anderson", name = "Aubergiste Anderson", note = "tient l'auberge au-dessus de sa cave" },
	},
})

Translate("frFR", "phin-odelic", {
	title = "Phin Odelic",
	subtitle = "En quête de la nouvelle peste",
	found = "L'auberge de Southshore",
	hint = [=[Parlez à l'homme de Southshore qui mène une troupe d'enquêteurs.]=],
	allegiance = "Southshore · Alliance",
	aliases = { "Phin" },
	sections = {
		{
			title = "Résumé",
			text = [=[Phin Odelic mène une petite troupe d'aventuriers qui enquêtent sur d'étranges événements dans les contreforts. Son cousin d'{link:hillsbrad-foothills}Hillsbrad{/link} dut abattre son chien, Stanley, après que la bête eut enflé jusqu'à une taille monstrueuse et se fut jetée sur tous ceux qui l'approchaient. Phin croit que les morts-vivants sont derrière tout cela.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il envoie chercher ses compagnons {link:quae}Quae{/link} et {link:kinelory}Kinelory{/link}, partis à la ferme de Go'Shek dans les {link:arathi-highlands}Hautes-terres d'Arathi{/link} et qui n'ont pas fait leur rapport.
• Il rassemble des preuves que les {link:forsaken}Réprouvés{/link} travaillent à une nouvelle peste.]=],
		},
	},
	chapters = {
		{
			title = "Indices d'une nouvelle peste",
			hint = [=[Retrouvez les compagnons disparus de Phin dans les Hautes-terres d'Arathi.]=],
			text = [=[{link:quae}Quae{/link} et {link:kinelory}Kinelory{/link} étaient vivants. Ils espionnaient les orcs de la ferme de Go'Shek, où il se passait plus de choses qu'il n'y paraissait, et Kinelory revint avec des objets qui en provenaient. Grâce à eux, Phin espérait enfin apprendre ce que faisaient les {link:forsaken}Réprouvés{/link}.]=],
		},
	},
	mentions = {
		{ text = "Indices d'une nouvelle peste ?" },
		{ text = "Indices d'une nouvelle peste ?" },
	},
	bonds = {
		{ id = "stanley", name = "Stanley", note = "le chien de son cousin" },
		{ id = "farmer-ray", name = "Fermier Ray", note = "le maître de Stanley" },
		{ id = "apothecary-lydon", name = "Apothicaire Lydon", note = "le fabricant du poison qu'il recherche" },
	},
})

Translate("frFR", "tom-half-fish-wilson", {
	title = "Tom « Demi-poisson » Wilson",
	subtitle = "Vieux marin de Southshore",
	found = "Les quais de Southshore",
	hint = "Trouvez le vieux marin sur les quais de Southshore.",
	allegiance = "Southshore",
	aliases = { "Demi-poisson" },
	sections = {
		{
			title = "Résumé",
			text = [=[Tom Wilson, que tout le monde appelle Demi-poisson, vit près des quais de {link:southshore}Southshore{/link}. Il a une rancune contre un homme de {link:menethil-harbor}Port de Menethil{/link} nommé {link:bart-tidewater}Bart Tidewater{/link}, qui se dit capitaine du {i}Maiden's Virtue{/i}. Tom affirme que Bart n'est pas du tout capitaine, seulement un acteur qui gagna son navire aux cartes, et qu'il triche.]=],
		},
		{
			title = "Importance",
			text = [=[Demi-poisson connaît les nouveaux navires qui font escale à {link:southshore}Southshore{/link}, et il sait lequel part pour Menethil.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il envoie un cadeau à {link:bart-tidewater}Bart Tidewater{/link}, à {link:menethil-harbor}Port de Menethil{/link}, à remettre avec ses compliments.]=],
		},
	},
	chapters = {
		{
			title = "Un manque de vertu",
			hint = "Portez le cadeau de Demi-poisson à Port de Menethil.",
			text = [=[{link:bart-tidewater}Bart Tidewater{/link} déballa le cadeau et faillit exploser. À l'en croire, c'était Tom qui trichait aux cartes, et il avait été chassé de leur cercle pour cela. L'or que Bart gagna ensuite paya le {i}Maiden's Virtue{/i}. Puis il se souvint de ses manières, et souhaita la bienvenue au messager à Menethil.]=],
		},
	},
	mentions = {
		{ text = "Un manque de vertu" },
