Translate("frFR", "apothecary-lydon", {
	title = "Apothicaire Lydon",
	subtitle = "Apothicaire de Moulin-de-Tarren",
	found = "Moulin-de-Tarren",
	hint = [=[Trouvez le sombre apothicaire de la Société à Moulin-de-Tarren.]=],
	allegiance = "Société royale des apothicaires · Réprouvés",
	aliases = { "Lydon" },
	sections = {
		{
			title = "Résumé",
			text = [=[L'apothicaire Lydon est l'homme de la {link:royal-apothecary-society}Société royale des apothicaires{/link} à {link:tarren-mill}Moulin-de-Tarren{/link}. C'est une âme morose, pour qui chaque jour de non-vie est une misère. Une seule chose lui remonte le moral : la souffrance des vivants. Son travail est de préparer la nouvelle peste de {link:sylvanas-windrunner}la Dame noire{/link} pour {link:hillsbrad-foothills}Hillsbrad{/link}, et il s'en acquitte avec soin et avec une gaieté terrible.]=],
		},
		{
			title = "Importance",
			text = [=[Le {link:master-apothecary-faranell}maître apothicaire Faranell{/link} dit de Lydon qu'il est l'un des membres les plus dévoués et les plus habiles de la Société. C'est avec ses élixirs que la peste destinée au {link:scourge}Fléau{/link} est pour la première fois tournée contre les humains.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il prépare trois élixirs, de souffrance, de douleur et d'agonie, chacun plus mortel que le précédent.
• Il les teste sur sa grenouille, Umpi, sur le chien du fermier {link:farmer-ray}Ray{/link} et sur des fermiers capturés.
• Il prépare pour l'{link:apothecary-zamah}apothicaire Zamah{/link} une toxine contre la {link:venture-company}KapitalRisk{/link} dans les {link:stonetalon-mountains}Serres-Rocheuses{/link}, à partir du sang d'innocents pris aux mages du {link:syndicate}Syndicat{/link}.
• Il étudie le venin du dieu araignée des {link:witherbark-trolls}trolls Witherbark{/link}, et l'envoie à {link:master-apothecary-faranell}Faranell{/link}.
• Les jours de morosité, il ouvre son bocal de formol pour en savourer l'arôme, ce qui rend Umpi nerveuse.]=],
		},
	},
	chapters = {
		{
			title = "L'élixir de douleur",
			hint = "Testez l'élixir de l'apothicaire sur un chien de ferme.",
			text = [=[Lydon voulait un essai. Il envoya son élixir à la ferme du nord des {link:hillsbrad-fields}Champs d'Hillsbrad{/link}, pour qu'on le donne en friandise au petit chien du fermier {link:farmer-ray}Ray{/link}, Stanley. Ce que le chien devint ensuite, son maître dut le tuer lui-même.]=],
		},
		{
			title = "L'élixir d'agonie",
			hint = [=[Apportez la préparation pestilentielle de l'apothicaire aux fermiers capturés.]=],
			text = [=[Le dernier élixir exigeait les fleurs puantes de la ferme des Nethander, un colloïde de la main même de {link:master-apothecary-faranell}Faranell{/link} et un tonnelet de stout naine de {link:dun-garok}Dun Garok{/link}. Puis Lydon fit déposer le tonnelet contaminé dans la salle où les {link:forsaken}Réprouvés{/link} gardaient leurs fermiers capturés. Il appelait cela leur offrir une fête.]=],
		},
	},
	mentions = {
		{
			text = [=[En route pour les contreforts d'{link:hillsbrad-foothills}Hillsbrad{/link}, de la part de l'apothicaire {link:apothecary-renferrel}Renferrel{/link}]=],
		},
		{ text = "Élixir de souffrance" },
		{ text = "Élixir de douleur" },
		{ text = "Élixir d'agonie" },
		{ text = "Élixir d'agonie" },
		{ text = "En route pour {link:tarren-mill}Moulin-de-Tarren{/link}" },
		{ text = "Le sang des innocents" },
		{ text = "Du venin pour {link:undercity}Undercity{/link}" },
	},
	bonds = {
		{ id = "master-apothecary-faranell", name = "Maître apothicaire Faranell", note = "son supérieur" },
		{ id = "apothecary-renferrel", name = "Apothicaire Renferrel", note = "partage ses découvertes" },
		{ id = "apothecary-zamah", name = "Apothicaire Zamah", note = "lui demanda une toxine" },
		{ id = "stanley", name = "Stanley", note = "son sujet d'essai" },
		{ id = "serge-hinott", name = "Serge Hinott", note = "travaille à ses côtés" },
	},
})

