Translate("frFR", "battle-of-hillsbrad", {
	title = "Bataille d'Hillsbrad",
	sections = {
		{
			title = "Résumé",
			text = [=[La bataille d'{link:hillsbrad-foothills}Hillsbrad{/link} est la guerre que les {link:forsaken}Réprouvés{/link} de {link:tarren-mill}Moulin-de-Tarren{/link} mènent aujourd'hui contre les humains des contreforts. Son but est clair : briser les humains d'Hillsbrad jusqu'à ce que les apothicaires achèvent la nouvelle peste, puis raser {link:southshore}Southshore{/link}.]=],
		},
		{
			title = "La campagne",
			text = [=[L'ordre vint de {link:varimathras}Varimathras{/link} à la grande exécutrice {link:high-executor-darthalia}Darthalia{/link}. Quand son éclaireuse de la tour de la Pointe du Midi fit savoir que la ville était mûre, l'attaque commença par étapes.

• {b}Les fermes.{/b} Les gardes de la Mort frappèrent d'abord les fermes du nord et leurs propriétaires, pour couper les vivres d'{link:hillsbrad-foothills}Hillsbrad{/link}.
• {b}Les vergers.{/b} Les paysans qui fuirent dans les vergers du sud y furent traqués.
• {b}La forge.{/b} Le forgeron et ses apprentis furent tués, et le fer de la ville fut emporté.
• {b}Le conseil.{/b} Le magistrat et le conseil furent désignés pour la mort, la charte de la ville pour le feu, et son registre pour le vol.
• {b}La mine.{/b} Le contremaître et les mineurs de la mine d'Azurelode furent attaqués, afin que {link:sylvanas-windrunner}la Dame noire{/link} puisse armer ses soldats grâce à elle.
• {b}{link:dun-garok}Dun Garok{/link}.{/b} Vint enfin le siège de la forteresse naine sur le mur de {link:thoradin}Thoradin{/link}.]=],
		},
		{
			title = "L'autre camp",
			text = [=[Les humains ne meurent pas en silence. Des habitants d'{link:hillsbrad-foothills}Hillsbrad{/link} ont tué des gardes, des apothicaires et des nervis de la mort réprouvés, et tendu des embuscades aux ravitaillements envoyés d'{link:undercity}Undercity{/link}. {link:high-executor-darthalia}Darthalia{/link} garde leurs noms sur une liste de primes.]=],
		},
		{
			title = "Les apothicaires",
			text = [=[Pendant que les soldats se battent, l'apothicaire {link:apothecary-lydon}Lydon{/link} teste ses élixirs sur les chiens et les fermiers capturés d'{link:hillsbrad-foothills}Hillsbrad{/link}. Chacun se veut un pas vers la peste qu'a ordonnée {link:sylvanas-windrunner}la Dame noire{/link}.]=],
		},
	},
})

Translate("frFR", "internment-camps", {
	title = "Camps d'internement",
	aliases = { "camp d'internement" },
	sections = {
		{
			title = "Résumé",
			text = [=[Après la {link:second-war}Deuxième Guerre{/link}, les orcs qui survécurent ne furent pas passés au fil de l'épée. On les rassembla dans des camps d'internement à travers {link:lordaeron}Lordaeron{/link}, gardés par les soldats de l'{link:alliance}Alliance{/link}. Les camps devaient servir à détenir un ennemi vaincu. Ils devinrent quelque chose de pire.]=],
		},
		{
			title = "La léthargie",
			text = [=[Coupés de la puissance démoniaque qui les avait animés, les orcs des camps devinrent apathiques et malades d'esprit. Beaucoup restaient simplement assis derrière les murs sans chercher à partir. Les humains qui les gardaient ne pouvaient le comprendre. Certains les prirent en pitié. D'autres en tirèrent profit.]=],
		},
		{
			title = "Durnholde",
			text = [=[Les camps étaient dirigés depuis le donjon de {link:durnholde-keep}Durnholde{/link}, à {link:hillsbrad-foothills}Hillsbrad{/link}, sous les ordres du lieutenant général {link:aedelas-blackmoore}Aedelas Blackmoore{/link}. Blackmoore voyait derrière ses murs plus que des prisonniers. Il voyait une armée qui pourrait être la sienne, si un {link:orcs}orc{/link} qu'il avait lui-même élevé la menait.]=],
		},
		{
			title = "La libération",
			text = [=[Cet {link:orcs}orc{/link} était {link:thrall}Thrall{/link}. Il s'échappa de {link:durnholde-keep}Durnholde{/link}, trouva les clans libres et apprit les voies du chaman. Avec {link:orgrim-doomhammer}Orgrim Doomhammer{/link} à ses côtés, il frappa les camps un à un et libéra les orcs qui s'y trouvaient. Doomhammer tomba lors de l'une de ces batailles. Enfin, Thrall vint à Durnholde même, et les camps prirent fin.]=],
		},
	},
})
